(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-952":{scenario:{company:"Dong Xanh Meat Products",supervisor:{name:"Vũ Thị Hằng",role:{vi:"Trưởng nhóm HACCP",en:"HACCP Team Leader"}},ref_code:"DEV-0517",title:{vi:"Đúng điểm tới hạn. Đủ lô nghi ngờ. Không xuất hàng chưa an toàn.",en:"Right CCP. Full suspect lot. No unsafe shipments."},brief:{vi:"Bạn hoàn thiện biên bản sai lệch DEV-0517 tại công đoạn nấu xúc xích gà. Đây là bước duy nhất tiêu diệt Salmonella và Listeria, có giới hạn tới hạn nhiệt độ tâm ≥ 72°C, giám sát 30 phút một lần. Lần đo 09:30 đạt 75°C, lần đo 10:00 chỉ 68°C, dây chuyền dừng lúc 10:15; công suất 1600 gói/giờ. Sửa phân loại biện pháp kiểm soát và số gói phải giữ lại, rồi lập báo cáo có căn cứ.",en:"You are completing deviation record DEV-0517 at the chicken sausage cooking step. This is the only step that kills Salmonella and Listeria, with a critical limit of core temperature ≥ 72°C monitored every 30 minutes. The 09:30 check read 75°C, the 10:00 check only 68°C, and the line stopped at 10:15; output is 1600 packs per hour. Correct the control category and the number of packs on hold, then write an evidence-based report."},reference_title:{vi:"Kế hoạch HACCP & nhật ký giám sát CCP đã duyệt · DEV-0517",en:"Approved HACCP plan & CCP monitoring log · DEV-0517"},fields:[{id:"CTRL_CAT",label:{vi:"Phân loại biện pháp kiểm soát bước nấu",en:"Control category of the cooking step"},initial:"OPRP",expected:"CCP",choices:["PRP","OPRP","CCP"],reference:"Bảng phân tích mối nguy & cây quyết định",hint:{vi:"Bước loại bỏ mối nguy đáng kể, có giới hạn tới hạn đo được và không có bước sau kiểm soát lại là điểm kiểm soát tới hạn.",en:"A step that eliminates a significant hazard, has a measurable critical limit and no later control is a critical control point."}},{id:"HOLD_PACKS",label:{vi:"Số gói phải giữ lại (gói)",en:"Packs to place on hold"},initial:"400",expected:"1200",reference:"Nhật ký giám sát nhiệt độ tâm",ref_value:{vi:"09:30 đạt 75°C; 10:00 không đạt 68°C; dừng chuyền 10:15; 1600 gói/giờ",en:"09:30 pass 75°C; 10:00 fail 68°C; line stopped 10:15; 1600 packs/hour"},hint:{vi:"Lô nghi ngờ bắt đầu từ lần giám sát đạt gần nhất, không phải từ lúc phát hiện sai lệch.",en:"The suspect lot starts at the last passing check, not at the moment the deviation was found."}}],sop32:{vi:"Lô nghi ngờ = toàn bộ sản phẩm từ lần giám sát đạt gần nhất trước sai lệch đến lúc dừng chuyền; số gói = thời gian (giờ) x công suất (gói/giờ).",en:"Suspect lot = all product from the last passing check before the deviation until the line stopped; packs = time (hours) x output (packs/hour)."},context:{label:"BIÊN BẢN SAI LỆCH / DEV-0517",metrics:[{label:{vi:"Giới hạn tới hạn",en:"Critical limit"},value:"≥ 72°C core"},{label:{vi:"Tần suất giám sát",en:"Monitoring frequency"},value:"30 min"},{label:{vi:"Công suất chuyền",en:"Line output"},value:"1600 /h"}]},crisis:{vi:"Trưởng ca nhắn: “Chỉ giữ 400 gói sau 10:00 thôi, hàng trước đó chắc chắn chín rồi. Xe giao hàng đang chờ, giữ cả lô là trễ hợp đồng với nhà phân phối.”",en:"The shift leader messages you: “Hold only the 400 packs after 10:00, everything before that was surely cooked. The truck is waiting and holding the whole lot will breach the distributor contract.”"},options:{safe:{vi:"Giữ đủ 1200 gói, lập biên bản sai lệch, báo trưởng nhóm HACCP và giám đốc chất lượng; đề xuất lấy mẫu vi sinh, đánh giá xử lý (nấu lại đã thẩm định hoặc hủy) và báo sớm nhà phân phối.",en:"Hold all 1200 packs, log the deviation and inform the HACCP leader and quality director; propose microbial sampling, a disposition review (validated recook or destruction) and early notice to the distributor."},shortcut:{vi:"Chỉ giữ 400 gói sau 10:00, giao phần còn lại cho kịp xe rồi theo dõi khiếu nại.",en:"Hold only the 400 packs after 10:00, ship the rest on time and watch for complaints."},wait:{vi:"Để nguyên hàng trên chuyền và chờ trưởng ca tự quyết định.",en:"Leave the product on the line and let the shift leader decide."}},questions:{vi:["Vì sao bước nấu là CCP chứ không phải OPRP, và vì sao phải giữ 1200 gói? Nhật ký nào chứng minh?","Bạn đề xuất hành động khắc phục, thẩm tra và trao đổi với nhà phân phối thế nào để kiểm soát rủi ro Listeria?"],en:["Why is the cooking step a CCP rather than an OPRP, and why must 1200 packs be held? Which log proves it?","What corrective action, verification and distributor communication do you propose to control the Listeria risk?"]},hints:{vi:["Đặt bảng phân tích mối nguy cạnh biên bản và trả lời từng câu của cây quyết định cho bước nấu.","Xác định lần giám sát đạt gần nhất trước sai lệch rồi tính thời lượng đến lúc dừng chuyền theo SOP mục 3.2.","Đọc lại SOP mục 4.2: sản phẩm nghi ngờ không được xuất khi chưa có đánh giá và phê duyệt của nhóm HACCP."],en:["Place the hazard analysis next to the record and answer each decision tree question for the cooking step.","Find the last passing check before the deviation and calculate the time to the line stop as in SOP 3.2.","Re-read SOP 4.2: suspect product cannot ship before the HACCP team has assessed and approved it."]}},learning:{summary:{vi:"Chuyên viên an toàn thực phẩm xây dựng, vận hành và duy trì hệ thống HACCP, ISO 22000 tại nhà máy: phân tích mối nguy, thiết lập chương trình tiên quyết, điểm kiểm soát tới hạn, giám sát, hành động khắc phục, thẩm tra và truy xuất. Công việc đòi hỏi hiểu vi sinh, hóa học thực phẩm, quy định pháp luật và bản lĩnh nói không với hàng chưa an toàn dù chịu áp lực tiến độ.",en:"A food safety specialist builds, runs and maintains the plant's HACCP and ISO 22000 system: hazard analysis, prerequisite programmes, critical control points, monitoring, corrective action, verification and traceability. The role requires microbiology, food chemistry and regulatory knowledge and the courage to say no to unsafe product under schedule pressure."},responsibilities:{vi:["Dẫn dắt nhóm HACCP phân tích mối nguy sinh học, hóa học, vật lý và chất gây dị ứng.","Xác định PRP, OPRP, CCP và thiết lập giới hạn tới hạn, tần suất giám sát.","Xử lý sai lệch: cách ly sản phẩm, hành động khắc phục, đánh giá và quyết định xử lý.","Thẩm tra hệ thống: đánh giá nội bộ, lấy mẫu kiểm nghiệm, diễn tập truy xuất và thu hồi.","Đào tạo nhân viên, làm việc với đoàn đánh giá chứng nhận và cơ quan quản lý."],en:["Lead the HACCP team in analysing biological, chemical, physical and allergen hazards.","Define PRPs, OPRPs and CCPs and set critical limits and monitoring frequency.","Handle deviations: hold product, take corrective action, assess and decide disposition.","Verify the system: internal audits, product testing, traceability and recall drills.","Train staff and work with certification auditors and regulators."]},competencies:[{name:{vi:"Phân tích mối nguy",en:"Hazard analysis"},desc:{vi:"Đánh giá khả năng xảy ra và mức độ nghiêm trọng để xác định mối nguy đáng kể.",en:"Assess likelihood and severity to identify significant hazards."}},{name:{vi:"Thiết kế kế hoạch HACCP",en:"HACCP plan design"},desc:{vi:"Áp dụng cây quyết định, đặt giới hạn tới hạn có căn cứ khoa học và cách giám sát phù hợp.",en:"Apply the decision tree and set science-based critical limits with suitable monitoring."}},{name:{vi:"Xử lý sai lệch & thu hồi",en:"Deviation & recall handling"},desc:{vi:"Khoanh đúng lô nghi ngờ, ra quyết định xử lý và điều phối thu hồi khi cần.",en:"Define the right suspect lot, decide disposition and coordinate recalls when needed."}},{name:{vi:"Đánh giá nội bộ",en:"Internal auditing"},desc:{vi:"Thu thập bằng chứng khách quan, phát hiện điểm không phù hợp và theo dõi khắc phục.",en:"Gather objective evidence, find nonconformities and follow up corrective actions."}},{name:{vi:"Bản lĩnh tuân thủ",en:"Compliance courage"},desc:{vi:"Giữ hàng nghi ngờ dù bị áp lực giao hàng và báo cáo minh bạch lên cấp có thẩm quyền.",en:"Hold suspect product despite delivery pressure and escalate transparently."}}],knowledge:{vi:["Nguyên tắc chung về vệ sinh thực phẩm Codex CXC 1-1969 với 12 bước, 7 nguyên tắc HACCP.","ISO 22000:2018 về hệ thống quản lý an toàn thực phẩm và cách phân biệt PRP, OPRP, CCP.","ISO/TS 22002-1 về chương trình tiên quyết trong sản xuất thực phẩm.","Luật An toàn thực phẩm số 55/2010/QH12 và các văn bản hướng dẫn.","Đặc tính vi sinh vật gây bệnh: Salmonella, Listeria monocytogenes, Clostridium perfringens."],en:["Codex General Principles of Food Hygiene CXC 1-1969 with the 12 steps and 7 HACCP principles.","ISO 22000:2018 on food safety management systems and the difference between PRP, OPRP and CCP.","ISO/TS 22002-1 on prerequisite programmes for food manufacturing.","Food Safety Law No. 55/2010/QH12 and its guiding documents.","Characteristics of pathogens: Salmonella, Listeria monocytogenes and Clostridium perfringens."]},tools:["Nhiệt kế đầu dò đã hiệu chuẩn","Máy dò kim loại & mẫu thử chuẩn","Bộ test ATP vệ sinh bề mặt","Phần mềm quản lý HACCP & truy xuất","Bảng kiểm đánh giá nội bộ"],kpis:{vi:["Tỷ lệ sai lệch CCP được phát hiện và xử lý đúng hạn.","Số khiếu nại về an toàn thực phẩm (mục tiêu bằng 0).","Thời gian truy xuất một lô hàng (mục tiêu dưới 2 giờ).","Tỷ lệ điểm không phù hợp được khắc phục đúng hạn."],en:["Share of CCP deviations detected and handled on time.","Food safety complaints (target zero).","Time to trace one lot (target under 2 hours).","Share of nonconformities closed on time."]},day:[{time:"07:00",vi:"Rà soát nhật ký giám sát CCP ca đêm và ký xác nhận hồ sơ.",en:"Review night-shift CCP monitoring logs and sign off the records."},{time:"08:30",vi:"Kiểm tra vệ sinh dây chuyền trước sản xuất, test ATP bề mặt tiếp xúc.",en:"Check pre-start line hygiene and run ATP tests on contact surfaces."},{time:"10:00",vi:"Xử lý sai lệch nhiệt độ tâm, cách ly lô nghi ngờ và lập biên bản.",en:"Handle a core temperature deviation, hold the suspect lot and record it."},{time:"14:00",vi:"Họp nhóm HACCP đánh giá tác động khi đổi nhà cung cấp gia vị.",en:"HACCP team meeting on the impact of a new spice supplier."},{time:"16:00",vi:"Đào tạo công nhân mới về vệ sinh cá nhân và phân khu sạch, bẩn.",en:"Train new workers on personal hygiene and clean and dirty zoning."}],mistakes:{vi:["Chỉ cách ly sản phẩm từ lúc phát hiện sai lệch thay vì từ lần giám sát đạt gần nhất.","Nhầm lẫn OPRP với CCP, đặt giới hạn tới hạn cho bước không đo lường được.","Ghi bù nhật ký giám sát sau ca, làm mất giá trị bằng chứng."],en:["Holding product only from when the deviation was found instead of from the last passing check.","Confusing OPRP with CCP and setting critical limits on steps that cannot be measured.","Back-filling monitoring logs after the shift, destroying their value as evidence."]},career:[{vi:"Nhân viên kiểm soát chất lượng (QC)",en:"Quality control officer"},{vi:"Chuyên viên an toàn thực phẩm",en:"Food safety specialist"},{vi:"Trưởng nhóm HACCP",en:"HACCP team leader"},{vi:"Giám đốc chất lượng & an toàn thực phẩm",en:"Quality & food safety director"}],glossary:[{term:"CCP",vi:"Điểm kiểm soát tới hạn: bước có giới hạn tới hạn đo được để kiểm soát mối nguy đáng kể.",en:"Critical control point: a step with a measurable critical limit controlling a significant hazard."},{term:"OPRP",vi:"Chương trình tiên quyết vận hành: biện pháp kiểm soát mối nguy đáng kể dùng tiêu chí hành động.",en:"Operational prerequisite programme: a control measure for a significant hazard using action criteria."},{term:"PRP",vi:"Chương trình tiên quyết: điều kiện nền về vệ sinh, nhà xưởng, kiểm soát động vật gây hại.",en:"Prerequisite programme: basic conditions such as hygiene, premises and pest control."},{term:"Critical limit",vi:"Giới hạn tới hạn: giá trị phân tách chấp nhận và không chấp nhận tại CCP.",en:"The value separating acceptable from unacceptable at a CCP."},{term:"Traceability",vi:"Truy xuất nguồn gốc: khả năng theo dõi lô hàng một bước trước và một bước sau trong chuỗi.",en:"Ability to follow a lot one step back and one step forward in the chain."}],quiz:[{q:{vi:"Điểm kiểm soát tới hạn (CCP) khác OPRP ở điểm nào?",en:"How does a CCP differ from an OPRP?"},options:{vi:["CCP chỉ áp dụng cho mối nguy vật lý","CCP có giới hạn tới hạn đo được, cho phép phát hiện kịp thời mất kiểm soát","OPRP không cần giám sát","OPRP chỉ dùng cho nhà xưởng"],en:["A CCP only covers physical hazards","A CCP has a measurable critical limit allowing timely detection of loss of control","An OPRP needs no monitoring","An OPRP only applies to buildings"]},answer:1,explain:{vi:"Theo ISO 22000:2018, CCP có giới hạn tới hạn đo được; OPRP dùng tiêu chí hành động có thể đo hoặc quan sát.",en:"Under ISO 22000:2018 a CCP has a measurable critical limit; an OPRP uses action criteria that can be measured or observed."}},{q:{vi:"Giám sát 1 giờ một lần, lần đạt cuối 13:00, phát hiện không đạt 14:00, dừng chuyền 14:30, công suất 800 gói/giờ. Có bao nhiêu gói nghi ngờ?",en:"Checks are hourly; last pass 13:00, fail found 14:00, line stopped 14:30, output 800 packs/hour. How many packs are suspect?"},options:{vi:["400","800","1600","1200"],en:["400","800","1600","1200"]},answer:3,explain:{vi:"Từ 13:00 đến 14:30 là 1.5 giờ x 800 gói/giờ = 1200 gói.",en:"From 13:00 to 14:30 is 1.5 hours x 800 packs/hour = 1200 packs."}},{q:{vi:"Trưởng ca yêu cầu xuất lô đang cách ly vì sai lệch CCP để kịp xe. Bạn làm gì?",en:"The shift leader wants to ship a lot on hold for a CCP deviation to catch the truck. What do you do?"},options:{vi:["Giữ lô, báo trưởng nhóm HACCP và chờ kết quả đánh giá","Xuất trước, xét nghiệm sau","Xuất một nửa lô","Đổi ngày sản xuất trên nhãn"],en:["Keep the hold, inform the HACCP leader and await the assessment","Ship now and test later","Ship half the lot","Change the production date on the label"]},answer:0,explain:{vi:"Sản phẩm sau sai lệch CCP chỉ được xuất khi đã đánh giá là an toàn; xuất sớm có thể gây ngộ độc và buộc thu hồi.",en:"Product after a CCP deviation ships only once assessed as safe; early release can cause illness and a recall."}},{q:{vi:"Theo Codex, hệ thống HACCP gồm bao nhiêu nguyên tắc?",en:"According to Codex, how many principles does HACCP have?"},options:{vi:["5 nguyên tắc","12 nguyên tắc","7 nguyên tắc","10 nguyên tắc"],en:["5 principles","12 principles","7 principles","10 principles"]},answer:2,explain:{vi:"HACCP có 7 nguyên tắc, nằm trong 12 bước áp dụng gồm 5 bước chuẩn bị ban đầu.",en:"HACCP has 7 principles within 12 application steps that include 5 preliminary steps."}}],tools_en:["Calibrated probe thermometer","Metal detector & standard test pieces","ATP surface hygiene test kit","HACCP & traceability management software","Internal audit checklist"]}}})})(window.KKR);
